15	const ImpactCategorySchema = z.enum(["technology", "application", "policy", "capital", "ethics"]);
16	const TopicCategorySchema = z.enum(["technology", "application", "policy", "capital", "ethics", "other"]);
17	
18	// ========== 子 Schema ==========
19	
20	const EntitySchema = z.object({
21	  name: z.string().min(1, "Entity name must not be empty"),
22	  confidence: z.number().min(0, "Confidence must be >= 0").max(1, "Confidence must be <= 1"),
23	});
24	
25	const EntitiesSchema = z.object({
26	  companies: z.array(EntitySchema),
27	  products: z.array(EntitySchema),
28	  people: z.array(EntitySchema),
29	  technologies: z.array(EntitySchema),
30	});
31	
32	const TopicSchema = z.object({
33	  label: z.string().min(1, "Topic label must not be empty"),
34	  category: TopicCategorySchema,
35	  confidence: z.number().min(0, "Confidence must be >= 0").max(1, "Confidence must be <= 1"),
36	});
37	
38	const SentimentSchema = z.object({
39	  overall: SentimentOverallSchema,
40	  score: z.number().min(-1, "Sentiment score must be >= -1").max(1, "Sentiment score must be <= 1"),
41	  confidence: z.number().min(0, "Confidence must be >= 0").max(1, "Confidence must be <= 1"),
42	});
43	
