45	  scope: ImpactScopeSchema,
46	  time_horizon: TimeHorizonSchema,
47	  category: ImpactCategorySchema,
48	  significance_score: z.number().min(1, "Significance score must be between 1 and 10").max(10, "Significance score must be between 1 and 10"),
49	  rationale: z.string().min(1, "Rationale must not be empty").max(200, "Rationale must be 200 characters or less"),
50	});
51	
52	const RawNewsSourceSchema = z.object({
53	  name: z.string().min(1, "Source name must not be empty"),
54	  type: SourceTypeSchema,
55	  url: z.string().url("Source URL must be a valid URL"),
