validate(items: RawNewsItem[]): ValidationResult {
  const seenIds = new Set<string>();
  const valid: RawNewsItem[] = [];
  const skipped: SkippedItem[] = [];
  const date = this.options?.date ?? new Date().toISOString().split('T')[0];
  const minContentLength = this.options?.minContentLength ?? 50;

  for (const item of items) {
    // Step 1: Schema validation
    const parseResult = RawNewsItemSchema.safeParse(item);
    if (!parseResult.success) {
      const zodErrors = parseResult.error.errors;
      const reason = zodErrors.map(e => `${e.path.join('.')}: ${e.message}`).join('; ');
      skipped.push({ id: item.id ?? '(missing)', reason });
      continue;
    }

    // Step 2: Additional content length check  
    if (item.content.length < minContentLength) {
      skipped.push({ id: item.id, reason: 'content too short' });
      continue;
    }

    // Step 3: Duplicate ID check
    if (seenIds.has(item.id)) {
      skipped.push({ id: item.id, reason: 'duplicate id' });
      continue;
    }

    seenIds.add(item.id);
