### validator.ts

```typescript
import { RawNewsItem, IngestSummary, SkippedItem } from '../schema/types.js';
import { RawNewsItemSchema } from '../schema/schemas.js';

export interface ValidationOptions {
  date?: string;
  minContentLength?: number;
}

export interface ValidationResult {
  valid: RawNewsItem[];
  skipped: SkippedItem[];
  summary: IngestSummary;
}

export class NewsValidator {
  private options: Required<ValidationOptions>;

  constructor(options?: ValidationOptions) {
    this.options = {
      date: options?.date ?? new Date().toISOString().split('T')[0],
      minContentLength: options?.minContentLength ?? 50,
    };
  }

  validate(items: RawNewsItem[]): ValidationResult {
    const seenIds = new Set<string>();
    const valid: RawNewsItem[] = [];
    const skipped: SkippedItem[] = [];
    const sourceDist: Record<string, number> = {};

    for (const item of items) {
      // Step 1: Schema validation
      const parseResult = RawNewsItemSchema.safeParse(item);
      if (!parseResult.success) {
        const zodErrors = parseResult.error.errors;
        const reason = zodErrors.map(e => `${e.path.join('.')}: ${e.message}`).join('; ');
        skipped.push({ id: item.id ?? '(missing)', reason });
        continue;
      }

      // Step 2: Content length check (only if schema didn't already catch it)
      if (item.content.length < this.options.minContentLength) {
        skipped.push({ id: item.id, reason: 'content too short' });
        continue;
      }

      // Step 3: Duplicate ID check
      if (seenIds.has(item.id)) {
        skipped.push({ id: item.id, reason: 'duplicate id' });
        continue;
      }

      seenIds.add(item.id);
      valid.push(item);

      // Track source distribution
      const sourceType = item.source.type;
      sourceDist[sourceType] = (sourceDist[sourceType] ?? 0) + 1;
    }

    const summary: IngestSummary = {
      date: this.options.date,
      total_input: items.length,
      validated: valid.length,
      skipped: skipped.length,
      skipped_reasons: skipped,
      source_distribution: sourceDist,
    };

    return { valid, skipped, summary };
  }
}
```

Wait, I have a concern about the content length check. The RawNewsItemSchema already has `z.string().min(50, "Content must be at least 50 characters long")`. So if `minContentLength` is 50 (default), items with content < 50 would already be caught by step 1 (schema validation) and wouldn't reach step 2.

The `content too short` check in step 2 is useful when `minContentLength` is set higher than 50 (e.g., 200). Then items with content between 50-199 would pass schema validation but be caught by the custom check.

This makes sense as a configurable business rule on top of schema validation.

