export type { ReaderOptions } from './reader.js';
export type { ValidationOptions, ValidationResult } from './validator.js';
export { NewsReader } from './reader.js';
export { NewsValidator } from './validator.js';

export interface IngestOptions {
  dataDir?: string;
  date?: string;
}

export async function runIngest(options?: IngestOptions): Promise<ValidationResult> {
  const logger = new Logger('INGEST');

  logger.info('Starting INGEST pipeline');

  const reader = new NewsReader({ dataDir: options?.dataDir });
  const items = await reader.loadAll();
  logger.info(`Loaded ${items.length} raw items from reader`);

  const validator = new NewsValidator({ date: options?.date });
  const result = validator.validate(items);

  logger.info(`Validation complete: ${result.summary.validated} valid, ${result.summary.skipped} skipped`);

  return result;
}
