      makeValidItem({
        source: { name: 'Bad', type: 'tech_media' } as any,
      }),
    ]);
    expect(result.valid.length).toBe(0);
    expect(result.skipped.length).toBe(1);
    expect(result.skipped[0].reason).toContain('source.url');
