import fs from 'fs';
import path from 'path';
import { Logger } from '../logger.js';
import { RawNewsItem } from '../schema/types.js';

// =============================================================================
// M1 Ingest — File Reader
// =============================================================================

export interface ReaderOptions {
  /** Directory containing raw .json news files. Defaults to "data/raw". */
  dataDir?: string;
}

/**
 * Resolve the default data directory relative to the current working directory.
 */
function defaultDataDir(): string {
  return path.resolve(process.cwd(), 'data', 'raw');
}

/**
 * NewsReader — scans a directory for .json files and loads them as RawNewsItem[].
 *
 * Each file should contain either an array of RawNewsItem objects or a single
 * RawNewsItem object (which is automatically wrapped into an array).
 * Files that cannot be parsed or read are skipped with a WARN log.
 */
export class NewsReader {
  private dataDir: string;
  private _files: string[];
  private logger: Logger;

  constructor(options?: ReaderOptions) {
    this.dataDir = options?.dataDir ?? defaultDataDir();
    this._files = [];
    this.logger = new Logger('INGEST');
  }

  /**
   * Scan the configured directory and return all matching .json file paths.
   * Returns an empty array if the directory does not exist or cannot be read.
   */
  listFiles(): string[] {
    try {
      if (!fs.existsSync(this.dataDir)) {
        this.logger.warn(`Data directory does not exist: ${this.dataDir}`);
        this._files = [];
        return [];
      }

      const entries = fs.readdirSync(this.dataDir);
      this._files = entries
        .filter((f) => f.endsWith('.json'))
        .map((f) => path.join(this.dataDir, f));

      if (this._files.length === 0) {
        this.logger.warn(`No .json files found in data directory: ${this.dataDir}`);
      }

      return [...this._files];
    } catch (err) {
      this.logger.warn(`Failed to list files in ${this.dataDir}`, { error: String(err) });
      this._files = [];
      return [];
    }
  }

  /**
   * Load all .json files from the configured directory and merge them into
   * a single flat array of RawNewsItem objects.
   *
   * Files that fail to parse are logged as WARN and skipped (they do not
   * interrupt the overall process).
   */
  async loadAll(): Promise<RawNewsItem[]> {
    const files = this.listFiles();
    if (files.length === 0) {
      return [];
    }

    const allItems: RawNewsItem[] = [];

    for (const filePath of files) {
      try {
        const items = await this.loadFile(filePath);
        allItems.push(...items);
      } catch (err) {
        this.logger.warn(`Skipping file ${filePath} due to error`, { error: String(err) });
      }
    }

    this.logger.info(`Loaded ${allItems.length} raw items from ${files.length} file(s)`);

    return allItems;
  }

  /**
   * Load and parse a single JSON file, returning RawNewsItem[].
   *
   * If the file contains a single object (not an array), it is automatically
   * wrapped in an array for uniform return type.
   *
   * @throws If the file cannot be read or JSON.parse fails.
   */
  async loadFile(filePath: string): Promise<RawNewsItem[]> {
    const raw = fs.readFileSync(filePath, 'utf-8');
    const parsed: unknown = JSON.parse(raw);

    if (Array.isArray(parsed)) {
      return parsed as RawNewsItem[];
    }

    // Single object — wrap in array
    return [parsed as RawNewsItem];
  }
}

import { RawNewsItem, IngestSummary, SkippedItem } from '../schema/types.js';
import { RawNewsItemSchema } from '../schema/schemas.js';

// =============================================================================
// M1 Ingest — Data Validator
// =============================================================================

export interface ValidationOptions {
  /** Current date for the summary, defaults to today's date (YYYY-MM-DD). */
  date?: string;
  /**
   * Minimum content length in characters. Items with content shorter than this
   * are skipped with reason "content too short". Defaults to 50, matching the
   * schema's built-in minimum.
   */
  minContentLength?: number;
}

export interface ValidationResult {
  /** Items that passed all validation checks. */
  valid: RawNewsItem[];
  /** Items that were skipped, along with their skip reasons. */
  skipped: SkippedItem[];
  /** Aggregate summary of the validation run. */
  summary: IngestSummary;
}

/**
 * NewsValidator — validates, cleans, and deduplicates RawNewsItem[] data.
 *
 * Validation pipeline for each item:
 * 1. Schema validation via RawNewsItemSchema.safeParse()
 * 2. Content length check against minContentLength
 * 3. Duplicate ID detection
 *
 * Items that fail any check are added to the `skipped` list with a reason.
 */
export class NewsValidator {
  private options: Required<ValidationOptions>;

  constructor(options?: ValidationOptions) {
    this.options = {
      date: options?.date ?? todayStr(),
      minContentLength: options?.minContentLength ?? 50,
    };
  }

  /**
   * Validate a batch of RawNewsItem objects.
   *
   * @param items - The raw items to validate.
   * @returns A ValidationResult containing the valid items, skipped items,
   *          and an aggregate summary.
   */
  validate(items: RawNewsItem[]): ValidationResult {
    const seenIds = new Set<string>();
    const valid: RawNewsItem[] = [];
    const skipped: SkippedItem[] = [];
    const sourceDist: Record<string, number> = {};
    const minContentLength = this.options.minContentLength;

    for (const item of items) {
      // ── Step 1: Schema validation ────────────────────────────────────
      const parseResult = RawNewsItemSchema.safeParse(item);
      if (!parseResult.success) {
        const reason = formatZodErrors(parseResult.error);
        skipped.push({ id: item.id ?? '(missing)', reason });
        continue;
      }

      // ── Step 2: Content length check ─────────────────────────────────
      // This catches items that pass the schema's built-in min(50) but fail
      // a stricter (configurable) threshold.
      if (item.content.length < minContentLength) {
        skipped.push({ id: item.id, reason: 'content too short' });
        continue;
      }

      // ── Step 3: Duplicate ID detection ───────────────────────────────
      if (seenIds.has(item.id)) {
        skipped.push({ id: item.id, reason: 'duplicate id' });
        continue;
      }

      // ── All checks passed ────────────────────────────────────────────
      seenIds.add(item.id);
      valid.push(item);

      // Track source distribution
      const sourceType = item.source.type;
      sourceDist[sourceType] = (sourceDist[sourceType] ?? 0) + 1;
    }

    const summary: IngestSummary = {
      date: this.options.date,
      total_input: items.length,
      validated: valid.length,
      skipped: skipped.length,
      skipped_reasons: skipped,
      source_distribution: sourceDist,
    };

    return { valid, skipped, summary };
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Get today's date as YYYY-MM-DD.
 */
function todayStr(): string {
  return new Date().toISOString().split('T')[0];
}

/**
 * Format Zod validation errors into a human-readable string.
 *
 * Example output: "title: Title must not be empty; content: Content must be at least 50 characters long"
 */
function formatZodErrors(error: { errors: Array<{ path: (string | number)[]; message: string }> }): string {
  return error.errors
    .map((e) => {
      const pathStr = e.path.length > 0 ? e.path.join('.') : '(root)';
      return `${pathStr}: ${e.message}`;
    })
    .join('; ');
}

import { Logger } from '../logger.js';
import { NewsReader } from './reader.js';
import { NewsValidator, ValidationResult } from './validator.js';

// =============================================================================
// M1 Ingest — Pipeline Entry Point
// =============================================================================

export type { ReaderOptions } from './reader.js';
export type { ValidationOptions, ValidationResult } from './validator.js';
export { NewsReader } from './reader.js';
export { NewsValidator } from './validator.js';

export interface IngestOptions {
  /** Directory containing raw .json news files. Defaults to "data/raw". */
  dataDir?: string;
  /** Date string (YYYY-MM-DD) for the ingest summary. Defaults to today. */
  date?: string;
}

/**
 * Execute the complete INGEST pipeline:
 *
 * 1. Read all .json files from the data directory (NewsReader)
 * 2. Validate, deduplicate, and compile statistics (NewsValidator)
 * 3. Return the validation result with summary
 *
 * Progress is logged at each stage using the "INGEST" logger module.
 *
 * @param options - Optional pipeline configuration.
 * @returns A ValidationResult containing valid items, skipped items, and summary.
 */
export async function runIngest(options?: IngestOptions): Promise<ValidationResult> {
  const logger = new Logger('INGEST');

  logger.info('Starting INGEST pipeline');

  // ── Phase 1: Read ─────────────────────────────────────────────────────
  logger.info('Phase 1: Reading news files', options?.dataDir ? { dataDir: options.dataDir } : undefined);
  const reader = new NewsReader({ dataDir: options?.dataDir });
  const items = await reader.loadAll();
  logger.info(`Phase 1 complete: Loaded ${items.length} raw item(s) from reader`);

  // ── Phase 2: Validate ─────────────────────────────────────────────────
  logger.info('Phase 2: Validating and cleaning data');
  const validator = new NewsValidator({ date: options?.date });
  const result = validator.validate(items);

  // ── Phase 3: Summary ──────────────────────────────────────────────────
  logger.info(
    `Phase 2 complete: ${result.summary.validated} valid, ${result.summary.skipped} skipped (of ${result.summary.total_input} total)`,
  );

  logger.info('INGEST pipeline finished successfully');

  return result;
}

