  // But other fixture files also exist in the directory, so total > 10
  const result = await runIngest({ dataDir: FIXTURES_DIR, date: '2026-06-01' });
  // All valid items across all fixture files should pass
  // valid-news (10) + mixed-news valid (8) + en-only-news (5) + high-risk-news (3) = 26
  expect(result.summary.validated).toBeGreaterThanOrEqual(26);
});

test('mixed-news fixture: skipped count reflects invalid items', async () => {
  const result = await runIngest({ dataDir: FIXTURES_DIR, date: '2026-06-01' });
  // invalid-news (8) + mixed-news invalid (2) = 10 schema-invalid items
  expect(result.summary.skipped).toBeGreaterThanOrEqual(10);
});

