function formatZodErrors(error: { issues: Array<{ path: (string | number)[]; message: string }> }): string {
  return error.issues
    .map((e) => {
      const pathStr = e.path.length > 0 ? e.path.join('.') : '(root)';
      return `${pathStr}: ${e.message}`;
    })
    .join('; ');
}

input.new_string:
function formatZodErrors(error: { issues: Array<{ path: (string | number | symbol)[]; message: string }> }): string {
  return error.issues
    .map((e) => {
      const pathStr = e.path.length > 0 ? e.path.map(String).join('.') : '(root)';
      return `${pathStr}: ${e.message}`;
    })
    .join('; ');
}
